import {forestJourney,decorations,decorateForest,waterForest} from './forest.js';

const asset=(id,cls='',style='')=>`<img src="assets/forest/${id}.webp" class="${cls}" style="${style}" alt="" loading="eager" draggable="false">`;
export function forestScene(s,area=forestJourney(s).area,highlight=false){
 const j=forestJourney(s),past=area<j.area,local=past?20:j.local,stage=past?4:j.stage;
 const trees=['tree_symbol_stage_01','tree_symbol_stage_02','tree_symbol_stage_03','tree_symbol_stage_04','tree_symbol_01'];
 const blooms=Array.from({length:local},(_,i)=>asset('flower_small_01','forest-bloom'+(highlight&&i===local-1?' forest-new':''),`left:${8+(i%10)*9}%;bottom:${2+Math.floor(i/10)*9}%;`)).join('');
 return `<div class="forest-scene" role="img" aria-label="${area+1}番目の森。${['芽','苗木','若木','大きな木','花咲く木'][stage]}。水やりで咲いた花${local}こ${local>=8?'。池ができた':''}${local>=12?'。動物が遊びに来た':''}">${asset('tree_pine_01','forest-back','left:0;')}${asset('tree_birch_01','forest-back','right:0;')}${local>=8?asset('pond_medium_01','forest-pond'):''}${local>=10?asset('bridge_medium_01','forest-bridge'):''}${asset(trees[stage],'forest-tree')}${local>=12?asset('rabbit_01','forest-animal'):''}${local>=16?asset('squirrel_01','forest-squirrel'):''}${local>=6?asset('flower_patch_01','forest-flowers'):''}${blooms}${highlight&&local?`<span class="forest-change-marker" aria-hidden="true" style="left:${12+((local-1)%10)*8.4}%;bottom:${17+Math.floor((local-1)/10)*9}%;">ここ！ ↓</span>`:''}${Array.from({length:6},(_,i)=>{const id=j.decor[`${area}:${i}`];return id?asset(id,'forest-decoration',`left:${12+(i%3)*32}%;top:${68+Math.floor(i/3)*17}%;`):'';}).join('')}<span class="forest-glints" aria-hidden="true">✦ · ✧</span></div>`;
}
export function forestSummary(s){const j=forestJourney(s);return `<div class="forest-summary"><strong>使える水 ${j.pending}回分</strong><span>あと${j.untilWater}問で、水をもう1回分ゲット</span><progress value="${j.water}" max="5" aria-label="次の水まで ${j.water}/5問"></progress><small>今日 ${j.today}問に挑戦 · 水やり ${j.watered}回 · 完成した森 ${j.area}こ</small></div>`;}
export function forestHome(s){const j=forestJourney(s);return `<section class="panel forest-home"><div class="section-head"><div><small class="eyebrow">YOUR ENGLISH FOREST</small><h2>学んで、水をやろう。</h2></div><a class="pill" href="#forest">森へ →</a></div>${j.pending?`<a class="button-link primary forest-water-entry" href="#forest">水 ${j.pending}回分 · 森で水をやる →</a>`:`<button class="primary start" data-forest-start="read" ${s.fast?.round&&s.fast.index<s.fast.ids.length?'data-forest-resume':''}>${s.fast?.round&&s.fast.index<s.fast.ids.length?'5問のつづき':'森を育てる5問'} →</button>`}${forestScene(s)}${forestSummary(s)}<small>水をやると、この森が変わるよ。水は何度でも集められるよ。</small></section>`;}
export function bindForestStarts({app,cards,mutate}){app.querySelectorAll('[data-forest-start]').forEach(b=>b.onclick=async()=>{if(b.hasAttribute('data-forest-resume')){location.hash='fast';return;}const {startForestRound}=await import('./fast.js');await mutate(s=>startForestRound(s,cards,b.dataset.forestStart));location.hash='fast';});}
export function forestReward(s){const j=forestJourney(s);return `<section class="forest-reward"><h2>${j.pending?'水を持って、森へ行こう！':'次の水まで、あと'+j.untilWater+'問'}</h2>${j.pending?`<p>使える水が${j.pending}回分あるよ。森の「水をやる」を押すと、変化が見えるよ。</p><a class="button-link primary" href="#forest">森で水をやる →</a>`:'<p>確かめた分は残っているよ。続きはいつでも大丈夫。</p>'}</section>`;}

let viewingArea=null,chosenDecoration=null,reveal=null,revealTimer;
export function cleanupForest(){clearTimeout(revealTimer);reveal=null;viewingArea=null;}
export function renderForest(ctx){
 const {app,state,mutate,tell}=ctx,j=forestJourney(state);
 if(reveal&&reveal.watered!==j.watered)reveal=null;
 let area=Math.min(viewingArea??j.area,j.area),selected=chosenDecoration||decorations.find(d=>d.rounds<=j.rounds)?.id;
 const draw=()=>{
  clearTimeout(revealTimer);
  const showing=reveal&&reveal.area===area,animating=showing&&performance.now()<reveal.until;
  app.innerHTML=`<div class="narrow forest-page"><a href="#home">← 学習にもどる</a><div class="section-head"><h1>わたしの英語の森</h1><span class="pill">水 ${j.pending}回分</span></div><p class="forest-instruction">${area<j.area?'この森は完成！ いつでも見に来られるよ。':j.pending?'「水をやる」を押して、森を育てよう。':'5問を確かめて、水を集めよう。'}</p><div class="forest-watering-stage ${animating?'is-watering':''}" id="forest-landscape">${forestScene(state,area,!!showing)}${animating?`<div class="forest-before" aria-hidden="true">${reveal.before}</div><span class="forest-water-drops" aria-hidden="true">💧 💧 💧</span>`:''}</div><div class="forest-water-result" role="status" aria-live="polite" tabindex="-1">${showing?`<strong>${reveal.change}</strong><span>水やり ${j.watered-1}回 → ${j.watered}回 · 花 ${(area<j.area?20:j.local)-1}こ → ${area<j.area?20:j.local}こ</span>`:'<span>水をやるたび、小さな花が1つ増えるよ。</span>'}</div><div class="forest-water-actions">${area<j.area?'<button id="forest-current" class="primary">いま育てている森へ →</button>':!j.pending&&!animating?(state.fast?.round&&state.fast.index<state.fast.ids.length?'<a class="button-link primary" href="#fast">5問のつづきへ →</a>':'<button id="forest-practice" class="primary" data-forest-start="read">'+(showing?'次の5問へ →':'5問で水を集める →')+'</button>'):`<button id="forest-water" class="primary" ${j.pending<1||animating?'disabled':''}>${animating?'水をやっているよ…':j.pending?'水をやる · 1回分':'使える水は0回分'}</button>`}<small>${j.pending?'水は1回分ずつ使えるよ。残りはあとで使っても大丈夫。':'水は何度でも集められるよ。休んでも森はそのまま。'}</small></div><div class="forest-area-nav"><button id="forest-prev" ${area===0?'disabled':''}>← 前の森</button><strong>${area+1}番目の森${area<j.area?' · 完成！':''}</strong><button id="forest-next" ${area===j.area?'disabled':''}>次の森 →</button></div><div class="actions forest-continue">${state.fast?.round&&state.fast.index<state.fast.ids.length?'<a class="button-link primary" href="#fast">5問のつづきへ →</a>':'<button class="primary" data-forest-start="read">次の5問へ →</button>'}<a href="#home">今日はここまで</a></div>${forestSummary(state)}<details class="panel"><summary>森をかざる・ほかの練習</summary><div class="actions"><button data-forest-start="listen">聞く5問</button><button data-forest-start="weak">苦手の5問</button><a href="#karuta">音声かるたへ</a></div><h2>森をかざろう</h2><p>${j.rounds?'飾りを選んで、置く場所をタップ。何度でも置きかえられるよ。':'5問チャレンジすると、小さな花が使えるよ。'}</p><div class="forest-palette">${decorations.map(d=>`<button data-decoration="${d.id}" aria-pressed="${selected===d.id}" ${d.rounds>j.rounds?'disabled':''}>${asset(d.id)}${d.name}<small>${d.rounds>j.rounds?'水をあと'+(d.rounds-j.rounds)+'回分集める':'使えるよ'}</small></button>`).join('')}</div><div class="forest-slots">${Array.from({length:6},(_,i)=>`<button data-slot="${i}" ${selected?'':'disabled'}>${state.forest?.decor[`${area}:${i}`]?asset(state.forest.decor[`${area}:${i}`]):'＋'}<small>場所${i+1}</small></button>`).join('')}</div><a href="#companion">ともだちの着せ替え →</a></details><details class="panel"><summary>森の育ち方</summary><p>5問ごとに水を1回分ゲット。森で水をやると花が1つ増えるよ。水やり4回ごとに木が育ち、8回で池、10回で橋、12回でウサギ、16回でリスが登場。20回で森が完成し、隣の森が広がるよ。</p><p>カードの確認・問題・かるた・実戦テストで水が集まるよ。「飛ばす」だけでは増えません。水と森は保存され、休んでも減りません。</p><small>水は挑戦の記録。XP・準備度とは別です。スターは訪問スタンプで1日1回もらえるよ。</small></details></div>`;
  bindForestStarts(ctx);
  app.querySelector('#forest-prev').onclick=()=>{viewingArea=--area;reveal=null;draw();};
  app.querySelector('#forest-next').onclick=()=>{viewingArea=++area;reveal=null;draw();};
  const current=app.querySelector('#forest-current');if(current)current.onclick=()=>{viewingArea=area=j.area;reveal=null;draw();};
  const water=app.querySelector('#forest-water');if(water)water.onclick=async()=>{
   if(water.disabled)return;water.disabled=true;
   const expected=j.watered;
   await mutate(s=>{const before=forestScene(s),result=waterForest(s,expected);if(!result){tell('森の記録が更新されたよ。残りの水を確かめてね。');return;}const motion=s.settings.motion&&!matchMedia('(prefers-reduced-motion: reduce)').matches;reveal={...result,before,until:performance.now()+(motion?1100:0)};viewingArea=result.area;});
   if(location.hash==='#forest'&&reveal&&performance.now()>=reveal.until)app.querySelector('.forest-water-result')?.focus({preventScroll:true});
  };
  app.querySelectorAll('[data-decoration]').forEach(b=>b.onclick=()=>{selected=b.dataset.decoration;chosenDecoration=selected;draw();});
  app.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>mutate(s=>decorateForest(s,area,+b.dataset.slot,selected)));
  if(animating)revealTimer=setTimeout(()=>{if(location.hash==='#forest'){draw();app.querySelector('.forest-water-result')?.focus({preventScroll:true});}},Math.max(0,reveal.until-performance.now()));
 };
 draw();
}
